export function gsibSnapshotSvg(lang, kind, mobile = false) {
  if (lang !== 'fr' && lang !== 'en') throw new TypeError('Unsupported G-SIB figure language');
  if (typeof kind !== 'string' || !GSIB_KINDS.includes(kind)) throw new TypeError('Unsupported G-SIB figure kind');
  if (typeof mobile !== 'boolean') throw new TypeError('mobile must be boolean');
  const number = String(GSIB_KINDS.indexOf(kind) + 1).padStart(2, '0');
  return SVG[`${number}-${lang}-${mobile ? 'mobile' : 'desktop'}`];
}

export function validateGsibSnapshotFigure(props) {
  if (!props || typeof props !== 'object' || Array.isArray(props)) throw new TypeError('Invalid G-SIB props');
  const { lang = 'fr', kind, number, caption, sources } = props;
  if (lang !== 'fr' && lang !== 'en') throw new TypeError('Invalid G-SIB language');
  if (typeof kind !== 'string' || !GSIB_KINDS.includes(kind)) throw new TypeError('Invalid G-SIB kind');
  if (typeof number !== 'string' || !/^0?[1-7]$/.test(number) || Number(number) !== GSIB_KINDS.indexOf(kind) + 1) throw new TypeError('Invalid G-SIB figure number');
  if (typeof caption !== 'string' || !caption.trim()) throw new TypeError('Invalid G-SIB caption');
  if (typeof sources !== 'string') throw new TypeError('Invalid G-SIB sources');
  const references = sources.trim().split(/\s+/);
  if (references.some(id => !/^S(?:0[1-9]|1[0-3])$/.test(id)) || new Set(references).size !== references.length) throw new TypeError('Invalid G-SIB sources');
  return { lang, kind, number: number.padStart(2, '0'), caption, references };
}
